-- PSORE V4.0 — Observatoire intégré des ouvrages
-- À exécuter après database/00_migration_complete_v2_4.sql

create extension if not exists pgcrypto;

create table if not exists public.forages_exploitation (
  id uuid primary key default gen_random_uuid(),
  code text unique not null,
  composante text not null check (composante in ('CRR','PM')),
  commune text not null,
  site text not null,
  forage text not null,
  x_utm double precision,
  y_utm double precision,
  epsg integer default 32629,
  longitude double precision,
  latitude double precision,
  etat text default 'POSITIF',
  hmt_m double precision,
  cote_installation_pompe_m double precision,
  debit_exploitation_m3h double precision,
  marque_pompe text,
  puissance_pompe_kw double precision,
  nombre_modules integer,
  puissance_module_w double precision,
  puissance_installee_kwc double precision,
  entreprise text,
  numero_compteur text,
  date_mise_service date,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table if not exists public.releves_prelevements (
  id uuid primary key default gen_random_uuid(),
  forage_id uuid not null references public.forages_exploitation(id) on delete cascade,
  date_releve date not null,
  index_compteur_m3 double precision,
  index_precedent_m3 double precision,
  volume_periode_m3 double precision,
  heures_pompage double precision,
  debit_observe_m3h double precision,
  niveau_statique_m double precision,
  niveau_dynamique_m double precision,
  usage text,
  incident text,
  observateur text,
  created_at timestamptz default now(),
  unique(forage_id,date_releve)
);

create table if not exists public.essais_pompage_piezometres (
  id uuid primary key default gen_random_uuid(),
  code_piezo text unique not null,
  site text not null,
  forage text,
  date_essai date,
  profondeur_totale_m double precision,
  profondeur_tubee_m double precision,
  crepine_superieure_m double precision,
  venue_eau_principale_m double precision,
  epaisseur_alterites_m double precision,
  niveau_statique_m double precision,
  debit_developpement_m3h double precision,
  debit_palier_1_m3h double precision,
  debit_palier_2_m3h double precision,
  debit_palier_3_m3h double precision,
  niveau_etiage_estime_m double precision,
  niveau_dynamique_max_m double precision,
  rabattement_max_m double precision,
  created_at timestamptz default now()
);

create table if not exists public.analyses_eau_piezometres (
  id uuid primary key default gen_random_uuid(),
  code_piezo text not null,
  site text not null,
  date_prelevement date,
  laboratoire text,
  ph double precision,
  conductivite_us_cm double precision,
  temperature_c double precision,
  turbidite_ntu double precision,
  tds_mg_l double precision,
  nitrates_mg_l double precision,
  nitrites_mg_l double precision,
  ammonium_mg_l double precision,
  chlorures_mg_l double precision,
  sulfates_mg_l double precision,
  fluorures_mg_l double precision,
  fer_mg_l double precision,
  manganese_mg_l double precision,
  coliformes_ufc_100ml double precision,
  e_coli_ufc_100ml double precision,
  conclusion_laboratoire text,
  document_source text,
  statut_validation text default 'A_SAISIR',
  created_at timestamptz default now()
);

create index if not exists idx_forages_exploitation_composante on public.forages_exploitation(composante);
create index if not exists idx_forages_exploitation_commune on public.forages_exploitation(commune);
create index if not exists idx_releves_prelevements_date on public.releves_prelevements(date_releve);
create index if not exists idx_analyses_eau_code on public.analyses_eau_piezometres(code_piezo);

alter table public.forages_exploitation enable row level security;
alter table public.releves_prelevements enable row level security;
alter table public.essais_pompage_piezometres enable row level security;
alter table public.analyses_eau_piezometres enable row level security;

drop policy if exists "lecture authentifiee forages exploitation" on public.forages_exploitation;
create policy "lecture authentifiee forages exploitation" on public.forages_exploitation for select to authenticated using (true);
drop policy if exists "lecture authentifiee essais piezo" on public.essais_pompage_piezometres;
create policy "lecture authentifiee essais piezo" on public.essais_pompage_piezometres for select to authenticated using (true);
drop policy if exists "lecture authentifiee analyses piezo" on public.analyses_eau_piezometres;
create policy "lecture authentifiee analyses piezo" on public.analyses_eau_piezometres for select to authenticated using (true);
drop policy if exists "gestion authentifiee prelevements" on public.releves_prelevements;
create policy "gestion authentifiee prelevements" on public.releves_prelevements for all to authenticated using (true) with check (true);

