create or replace view public.v_forages_exploitation_suivi as
select f.*,
       max(r.date_releve) as derniere_date_releve,
       max(r.index_compteur_m3) filter (where r.date_releve = (select max(r2.date_releve) from public.releves_prelevements r2 where r2.forage_id=f.id)) as dernier_index_compteur_m3,
       coalesce(sum(r.volume_periode_m3),0) as volume_total_releve_m3
from public.forages_exploitation f
left join public.releves_prelevements r on r.forage_id=f.id
group by f.id;

comment on table public.forages_exploitation is 'Référentiel des 16 forages d’exploitation CRR et PM';
comment on table public.releves_prelevements is 'Relevés périodiques des compteurs et niveaux des forages exploités';
comment on table public.essais_pompage_piezometres is 'Résultats initiaux des essais de pompage des 20 piézomètres';
comment on table public.analyses_eau_piezometres is 'Résultats physico-chimiques et bactériologiques des piézomètres';
